import{_ as e,o as a,c as d,a3 as r}from"./chunks/framework.DeRSg1wr.js";const g=JSON.parse('{"title":"如何选择你的接入方式","description":"TLog 2.0 统一使用日志配置接入，按应用框架选择依赖和入口适配。","frontmatter":{"title":"如何选择你的接入方式","date":"2022-09-12T13:26:10.000Z","permalink":"/pages/9c24c3/","description":"TLog 2.0 统一使用日志配置接入，按应用框架选择依赖和入口适配。"},"headers":[],"relativePath":"pages/9c24c3/index.md","filePath":"10.文档/030.如何选择你的接入方式.md"}'),o={name:"pages/9c24c3/index.md"};function c(n,t,l,i,s,p){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="如何选择你的接入方式" tabindex="-1">如何选择你的接入方式 <a class="header-anchor" href="#如何选择你的接入方式" aria-label="Permalink to &quot;如何选择你的接入方式&quot;">​</a></h1><p>TLog 2.0 只有日志配置文件接入方式。先加入适配当前应用的依赖，再配置日志标签输出；不再按 javaagent、字节码注入和日志适配器三种方式选择。</p><table tabindex="0"><thead><tr><th>应用场景</th><th>接入步骤</th></tr></thead><tbody><tr><td>Spring Boot Servlet / WebFlux</td><td>加入对应 starter，保留应用自己的 Web 和日志依赖，配置 MDC 或日志适配器</td></tr><tr><td>Spring Boot Feign / Dubbo / 网关</td><td>加入对应 TLog starter；如果应用也有 HTTP 入口，一并加入 Web 适配</td></tr><tr><td>非 Boot Spring 应用</td><td>使用实现模块，手工声明 TLog 组件，见<a href="/pages/d81b62/">Spring 项目接入</a>和<a href="/pages/8110af/">其他配置</a></td></tr><tr><td>纯 Java 客户端或任务</td><td>使用实现模块，手工建立/清理入口上下文，安装客户端拦截器并包装执行器</td></tr><tr><td>外置 Servlet 容器</td><td>注册与容器命名空间匹配的 Filter，并配置 REQUEST、ASYNC、ERROR 和 asyncSupported</td></tr></tbody></table><h2 id="日志输出选择" tabindex="-1">日志输出选择 <a class="header-anchor" href="#日志输出选择" aria-label="Permalink to &quot;日志输出选择&quot;">​</a></h2><ul><li>希望把标签放在固定位置：使用 MDC 的 <code>%X{tl}</code>。<code>tl</code> 是完整标签，也可单独输出 <code>tlogTraceId</code> 和 <code>tlogSpanId</code>。</li><li>希望保留已有 TLog encoder/layout/converter：继续使用<a href="/pages/5223de/">日志适配器</a>。不要同时让两套配置重复输出同一标签。</li><li>使用日志异步 appender：让日志事件在业务线程捕获 MDC，或使用 TLog 异步适配器。业务线程池的透传是另一件事，仍需按<a href="/pages/a69e1d/">异步文档</a>配置。</li></ul><div class="warning custom-block"><p class="custom-block-title">从 1.x 升级</p><p>删除 <code>-javaagent:tlog-agent.jar</code> 和 <code>AspectLogEnhance.enhance()</code>。这两种入口在 2.0 中已移除，不是关闭某个配置后还能继续使用的功能。步骤见<a href="/guide/upgrade/">升级指南</a>。</p></div>',6)])])}const h=e(o,[["render",c]]);export{g as __pageData,h as default};
